<script>
(function(){
const form=document.getElementById('purchaseInvoiceEdit'),rows=document.getElementById('purchaseInvoiceRows'),modal=document.getElementById('serialModal'),box=modal.querySelector('#serialNumberBox');
const text={remove:@json(__('purchases.remove')),auto:@json(__('purchases.auto')),placeholder:@json(__('common.enter_serial_number')),capacity:@json(__('purchases.serials_exceed_qty')),locked:@json(__('purchases.serial_unavailable'))};
let active=null,counter=0,modalInstance=null;
function count(row){return row.querySelectorAll('[data-new-serial]').length+Array.from(row.querySelectorAll('[data-existing-serial]')).filter(el=>el.dataset.active==='1'&&!row.querySelector('[data-removed-serial][value="'+el.dataset.id+'"]')).length;}
function recalc(){let total=0;rows.querySelectorAll('.invoice-item').forEach(row=>{const line=(Number(row.querySelector('[data-qty]').value)||0)*(Number(row.querySelector('[data-price]').value)||0);row.querySelector('[data-line-total]').textContent=line.toFixed(2);total+=line;row.querySelector('[data-serial-count]').textContent=count(row);});const discount=document.getElementById('discountType').value==='2'?total*(Number(document.getElementById('invoicePercent').value)||0)/100:Number(document.getElementById('invoiceDiscount').value)||0;document.getElementById('purchaseInvoicePreview').textContent=Math.max(0,total-discount).toFixed(2);}
function hidden(name,value,marker){const el=document.createElement('input');el.type='hidden';el.name=name;el.value=value;el.setAttribute(marker,'');return el;}
function sync(){if(!active)return;const payload=active.querySelector('[data-serial-payload]'),key=active.dataset.key;payload.querySelectorAll('[data-new-serial],[data-removed-serial]').forEach(el=>el.remove());box.querySelectorAll('.serial-input-row').forEach(row=>{const field=row.querySelector('input'),id=row.dataset.id;if(id){const original=payload.querySelector('[data-existing-serial][data-id="'+id+'"]');original.disabled=row.dataset.removed==='1';if(original.disabled)payload.appendChild(hidden('rows['+key+'][remove_serials][]',id,'data-removed-serial'));else original.value=field.value.trim();}else if(field.value.trim())payload.appendChild(hidden('rows['+key+'][serials][]',field.value.trim(),'data-new-serial'));});recalc();}
function capacity(){const qty=Number(active.querySelector('[data-qty]').value)||0,n=Array.from(box.children).filter(row=>row.dataset.removed!=='1'&&row.dataset.active!=='0').length;modal.querySelector('#add-serial').disabled=n>=qty;modal.querySelector('#autoGenerateSerials').disabled=n>=qty;}
function serialRow(value,source){const row=document.createElement('div');row.className='serial-input-row d-flex mb-3 align-items-center';row.innerHTML='<input type="text" class="form-control flex-grow-1" style="margin-right:12px" maxlength="255"><div class="d-flex"><button type="button" class="btn btn-sm btn-outline-danger remove-serial"></button><button type="button" class="btn btn-sm btn-outline-info auto-gen-serial-row" style="margin-left:6px"></button></div>';const field=row.querySelector('input');field.value=value;field.placeholder=text.placeholder;field.setAttribute('aria-label',text.placeholder);row.querySelector('.remove-serial').textContent=text.remove;row.querySelector('.auto-gen-serial-row').textContent=text.auto;if(source){row.dataset.id=source.dataset.id;row.dataset.active=source.dataset.active;const locked=source.dataset.locked==='1';field.readOnly=locked;row.querySelectorAll('button').forEach(button=>button.disabled=locked);if(locked)row.title=text.locked;}box.appendChild(row);return row;}
function show(row){sync();active=row;box.replaceChildren();row.querySelectorAll('[data-existing-serial]').forEach(el=>{const item=serialRow(el.value,el);if(row.querySelector('[data-removed-serial][value="'+el.dataset.id+'"]')){item.dataset.removed='1';item.hidden=true;item.classList.remove('d-flex');}});row.querySelectorAll('[data-new-serial]').forEach(el=>serialRow(el.value));if(!box.children.length)serialRow('');capacity();if(window.bootstrap?.Modal)(modalInstance ||= new window.bootstrap.Modal(modal)).show();else if(window.jQuery)window.jQuery(modal).modal('show');}
function hide(){if(window.bootstrap?.Modal)modalInstance?.hide();else if(window.jQuery)window.jQuery(modal).modal('hide');}
function generated(){return 'SN-'+Date.now()+'-'+Math.random().toString(36).slice(2,10);}
modal.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||!active)return;if(target.classList.contains('remove-serial')){const row=target.closest('.serial-input-row');if(row.dataset.id){row.dataset.removed='1';row.hidden=true;row.classList.remove('d-flex');}else row.remove();}else if(target.classList.contains('auto-gen-serial-row'))target.closest('.serial-input-row').querySelector('input').value=generated();else if(target.id==='add-serial')serialRow('');else if(target.id==='autoGenerateSerials'){const qty=Number(active.querySelector('[data-qty]').value)||0;box.querySelectorAll('.serial-input-row:not([data-id]) input').forEach(el=>{if(!el.value.trim())el.value=generated();});while(Array.from(box.children).filter(row=>row.dataset.removed!=='1'&&row.dataset.active!=='0').length<qty)serialRow(generated());}else if(target.hasAttribute('data-onclick')){box.querySelectorAll('.serial-input-row:not([data-id])').forEach(row=>row.remove());sync();hide();}else if(target.hasAttribute('data-dismiss')){sync();hide();}capacity();});
modal.addEventListener('hidden.bs.modal',sync);if(window.jQuery)window.jQuery(modal).on('hidden.bs.modal',sync);
rows.addEventListener('click',event=>{if(event.target.closest('[data-edit-serials]'))show(event.target.closest('.invoice-item'));if(event.target.closest('[data-remove-item]')){const row=event.target.closest('.invoice-item');event.preventDefault();window.RNConfirmItemRemoval(row,()=>{if(active===row){active=null;hide();}row.remove();recalc();form.dispatchEvent(new Event('purchase-item-removed'));});}});
document.getElementById('purchaseInvoiceAddRow').addEventListener('click',()=>{let key;do{key='new'+(++counter);}while(Array.from(rows.children).some(row=>row.dataset.key===key));const holder=document.createElement('tbody');holder.innerHTML=document.getElementById('purchaseInvoiceNewRow').innerHTML.replace(/__KEY__/g,key);rows.appendChild(holder.firstElementChild);recalc();});
document.querySelector('[data-rn-product-picker][data-mode="purchase"]')?.addEventListener('rn:product-picker:selected',event=>{const item=event.detail||{};document.getElementById('purchaseInvoiceAddRow').click();const row=rows.lastElementChild;if(!row)return;const product=row.querySelector('select[name$="[product_id]"]');if(product){product.value=String(item.id||item.product_id||'');product.dispatchEvent(new Event('change',{bubbles:true}));}row.querySelector('[data-qty]').value=String(item.quantity||1);row.querySelector('[data-price]').value=String(item.buy_price||0);row.querySelector('input[name$="[sale_price]"]').value=String(item.sale_price||0);form.dispatchEvent(new Event('input',{bubbles:true}));});
form.addEventListener('input',recalc);form.addEventListener('change',recalc);form.addEventListener('submit',event=>{sync();let invalid=false;rows.querySelectorAll('.invoice-item').forEach(row=>{const exceeds=count(row)>Number(row.querySelector('[data-qty]').value);row.querySelector('[data-serial-error]').textContent=exceeds?text.capacity:'';invalid=invalid||exceeds;});if(invalid)event.preventDefault();});recalc();
})();
</script>
